www.google.com.css:
span {
  font-family: 'Whitney', system-ui,sans-serif !important;
}

em {
  font-family: 'Whitney Semibold', system-ui, sans-serif !important;
}

h3 {
  font-family: 'Geologica', system-ui, sans-serif !important;
  font-weight: 300;
}

a {
  transition: all 0.12s ease-out;
  text-decoration: none;
}

a:hover {
  color: #ff0090;
  text-decoration: underline;
}

